package com.primehr.evidence;
import com.primehr.evidence.application.EvidenceFrameworkService;import com.primehr.evidence.api.EvidenceFrameworkDtos.*;import com.primehr.evidence.domain.EvidenceRequirement.EvidenceType;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.List;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("flyway-h2") @Transactional
class EvidenceFrameworkServiceIntegrationTest{
 @Autowired EvidenceFrameworkService service;
 @BeforeEach void actor(){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("admin",null,List.of()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void completeFrameworkPublishesAndRevisionCopiesImmutableContent(){var draft=service.create("A",new FrameworkInput("PRIME_ESG","PRIME-ESG Internal Readiness",null,"CSC","MC 11 s. 2026","Agency office order","Internal self-assessment support only; not an official CSC determination",null),"corr");var content=service.replaceContent("A",draft.id(),new ContentInput(draft.recordVersion(),List.of(new PillarInput("HR_GOV","HR Governance",null,1)),List.of(new LevelInput("GL1","Governance Level 1","Reference label only",1)),List.of(new IndicatorInput("HR_GOV","IND-1","Policy governance",null,"Validate against the published agency policy",1)),List.of(new RequirementInput("IND-1","REQ-1","Approved policy","Link the approved policy and authority",EvidenceType.POLICY,12,365,true,false,1))),"corr");var published=service.publish("A",draft.id(),new Publish(content.recordVersion(),LocalDate.of(2026,10,18),null,"Approved internal framework"),"corr");assertThat(published.status()).isEqualTo("PUBLISHED");assertThat(service.effective("A",LocalDate.of(2026,11,1)).id()).isEqualTo(published.id());var revision=service.revise("A",published.id(),new Transition(published.recordVersion(),"Annual revision"),"corr");assertThat(revision.status()).isEqualTo("DRAFT");assertThat(revision.definitionVersion()).isEqualTo(2);assertThat(revision.pillars()).hasSize(1);assertThat(revision.levels()).allMatch(LevelResponse::referenceOnly);assertThat(revision.requirements()).extracting(RequirementResponse::code).containsExactly("REQ-1");}
}
